const STYLE_SUFFIX = ", casual mobile game 3D icon, exaggerated soft claymation-style 3D render, plasticine clay aesthetic, matte plastic material with gentle soft sheen (not shiny or reflective), soft diffused studio lighting with subtle rim light, extremely smooth rounded puffy forms with no sharp edges, a few readable characteristic details preserved, harmonious vibrant contrasting color palette, medium level of detail, entire image in sharp focus with no depth of field blur, background rendered with the same quality and sharpness as the main object, consistent art direction across the entire set";

const rawText = $json.choices[0].message.content;
const cleaned = rawText.replace(/```json|```/g, '').trim();

let cards;
try {
  cards = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Ответ Groq оборвался или невалиден. Длина ответа: ' + rawText.length + ' символов. Конец ответа: ...' + rawText.slice(-200));
}

cards = cards.map(c => ({ ...c, prompt: c.prompt + STYLE_SUFFIX }));

const staticData = $getWorkflowStaticData('global');
staticData.cardsList = cards.map(c => ({ name: c.name, category: c.category }));

return cards.map(card => ({
  json: { ...card, chatId: staticData.chatId, folderPath: staticData.folderPath }
}));

const items = $input.all();
const binary = {};

items.forEach((item, i) => {
  const key = i === 0 ? 'data' : 'data' + i;
  binary[key] = item.binary.data;
});

return [{ json: {}, binary: binary }];

const sharp = require('sharp');

const keys = ['data','data1','data2','data3','data4','data5','data6','data7','data8','data9'];
const tileSize = 1024;
const cols = 5;
const rows = 2;

const composites = [];
for (let i = 0; i < keys.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, keys[i]);
  const resized = await sharp(buffer)
    .resize(tileSize, tileSize, { fit: 'cover' })
    .toBuffer();

  composites.push({
    input: resized,
    left: (i % cols) * tileSize,
    top: Math.floor(i / cols) * tileSize
  });
}

const canvas = sharp({
  create: {
    width: tileSize * cols,
    height: tileSize * rows,
    channels: 4,
    background: { r: 255, g: 255, b: 255, alpha: 1 }
  }
}).composite(composites).jpeg({ quality: 85 });

const outputBuffer = await canvas.toBuffer();
const finalBinary = await this.helpers.prepareBinaryData(outputBuffer, 'grid.jpg', 'image/jpeg');

return [{ json: {}, binary: { data: finalBinary } }];

