const rawText = $json.choices[0].message.content;
const cleaned = rawText.replace(/```json|```/g, '').trim();
const objects = JSON.parse(cleaned);

const staticData = $getWorkflowStaticData('global');

return [{
  json: {
    chatId: staticData.chatId,
    theme: staticData.theme,
    wishes: staticData.wishes,
    themeObjects: objects
  }
}];

const s = $getWorkflowStaticData('global');

const elapsedMs = Date.now() - s.startTime;
const minutes = Math.floor(elapsedMs / 60000);
const seconds = Math.floor((elapsedMs % 60000) / 1000);
const elapsedText = minutes > 0 ? `${minutes} мин ${seconds} сек` : `${seconds} сек`;

const cardsListText = s.cardsList
  .map((c, i) => `${i + 1}. ${c.name} — категория ${c.category}`)
  .join('\n');

const text = `🎬 Коллекция: Кино\n🎞 Тема набора: ${s.theme}\n\n🃏 Карточки:\n${cardsListText}\n\n⏱ Время генерации: ${elapsedText}\n📂 Путь: ${s.folderPath}`;

return [{
  json: {
    chatId: s.chatId,
    text: text
  }
}];

const fs = require('fs');

const staticData = $getWorkflowStaticData('global');
const safeName = $json.name.replace(/[<>:"/\\|?*]/g, '').trim();
const targetFolder = `${staticData.folderPath}\\cat${$json.category}_${safeName}`;

fs.mkdirSync(targetFolder, { recursive: true });

return [{
  json: { ...$json, safeFolderPath: targetFolder },
  binary: $binary
}];

const response = $json.result || $json;
const base64Image = response.image;

if (!base64Image) {
  throw new Error('Не нашёл картинку в ответе Cloudflare. Реальный ответ: ' + JSON.stringify($json).slice(0, 300));
}

const buffer = Buffer.from(base64Image, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'variant.png', 'image/png');

return [{
  json: { ...$('Wait').item.json },
  binary: { data: binaryData }
}];

